scripts.script:
--Inf Coins
local args = {
    [1] = "1000000000000000000000000",
    [2] = true
}

game:GetService("ReplicatedStorage").Orb:FireServer(unpack(args))

--Inf Gems
local args = {
    [1] = "100000000000000000000000",
    [2] = true
}

game:GetService("ReplicatedStorage").Orb2:FireServer(unpack(args))

--Unlock Best Wepon
local args = {
    [1] = "Lava Axe",
    [2] = 0
}

game:GetService("ReplicatedStorage").ClickBuy:FireServer(unpack(args))
local args = {
    [1] = 12000,
    [2] = 11,
    [3] = 0.6,
    [4] = 2.5
}

game:GetService("ReplicatedStorage").ClickEquip:FireServer(unpack(args))

-- Rent all Rings and change Length time to 15 hours instead of 15 minutes and Spawn Kill Part on Ring Floors (Copy all of them)
for i,v in pairs(game:GetService("Workspace").PrivateRings:GetChildren()) do
local args = {
    [1] = "Owner"
}

v.RentARing.ChangeInfoClient:FireServer(unpack(args))
local args = {
    [1] = "Time",
    [2] = {
        ["Type"] = "Hours",
        ["Length"] = 15
    }
}

v.RentARing.ChangeInfoClient:FireServer(unpack(args))
local args = {
    [1] = "Fighters",
    [2] = {
        [1] = ""..game:GetService("Players").LocalPlayer.Name
    }
}

v.RentARing.ChangeInfoClient:FireServer(unpack(args))
local args = {
    [1] = "MatchType",
    [2] = "RentBR"
}

v.RentARing.ChangeInfoClient:FireServer(unpack(args))
end

-- Spawn Bots
game:GetService("RunService").RenderStepped:Connect(function()
for i,v in pairs(game:GetService("Workspace").PrivateRings:GetChildren()) do
local args = {
    [1] = "AddBot"
}

v.RentARing.ChangeInfoClient:FireServer(unpack(args))
end
end)
